#requires -Version 7.0
<#
.SYNOPSIS
    Kundenneutrales Werkzeug zum Sichern und Wiederherstellen lokaler Windows-Benutzerdaten.
.DESCRIPTION
    Fuer wiederverwendbare Kundenumgebungen. Ohne Parameter wird nur der sichere Audit-Modus ausgefuehrt.
    Export und Import muessen explizit gewaehlt werden. Kennwoerter, Credential Manager, private
    Zertifikatschluessel und Outlook-OST-Dateien werden nicht migriert.
.NOTES
    Author: Hubert Josef Inderwildi
    License: MIT
    Version: 2.0.0.0
    Requires: Windows, PowerShell 7+, robocopy.exe fuer Export/Import
.SECURITY
    WLAN-Profile koennen Klartext-Schluessel enthalten. Der Export ist standardmaessig deaktiviert und
    erfordert -IncludeWifiProfiles und -AllowClearTextWifiKeys.
#>
[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='Medium')]
param(
 [ValidateSet('Audit','Export','Import')][string]$Mode,
 [ValidateNotNullOrEmpty()][string]$BackupRoot,
 [switch]$IncludeDownloads,[switch]$IncludeWifiProfiles,[switch]$AllowClearTextWifiKeys,
 [switch]$SkipNetworkDriveRestore,[switch]$SkipPrinterRestore
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
# ============================================================================
# CONFIGURATION BLOCK - safe customer-neutral defaults; parameters override.
# ============================================================================
$Configuration=[ordered]@{Mode='Audit';BackupRoot=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'WindowsUserMigration';IncludeDownloads=$false;IncludeWifiProfiles=$false;AllowClearTextWifiKeys=$false;SkipNetworkDriveRestore=$false;SkipPrinterRestore=$false;RobocopyRetryCount=2;RobocopyWaitSeconds=2;ExcludedFilePatterns=@('*.ost','*.tmp');ScriptVersion='2.0.0.0'}
foreach($k in @('Mode','BackupRoot','IncludeDownloads','IncludeWifiProfiles','AllowClearTextWifiKeys','SkipNetworkDriveRestore','SkipPrinterRestore')){if($PSBoundParameters.ContainsKey($k)){$Configuration[$k]=$PSBoundParameters[$k]}}
$script:MigrationLogFile=$null
function Write-MigrationLog{[CmdletBinding()]param([Parameter(Mandatory)][string]$Message,[ValidateSet('INFO','WARN','ERROR')][string]$Level='INFO');$l='{0} [{1}] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$Level,$Message;Write-Host $l;if($script:MigrationLogFile){Add-Content -LiteralPath $script:MigrationLogFile -Value $l -Encoding utf8}}
function New-DirectoryIfMissing{[CmdletBinding(SupportsShouldProcess)]param([Parameter(Mandatory)][string]$Path);if(-not(Test-Path -LiteralPath $Path -PathType Container)){if($PSCmdlet.ShouldProcess($Path,'Create directory')){New-Item -ItemType Directory -Path $Path -Force|Out-Null}}}
function Get-CurrentUserFolderPath{[CmdletBinding()]param([Parameter(Mandatory)][System.Environment+SpecialFolder]$SpecialFolder,[Parameter(Mandatory)][string]$FallbackName);$p=[Environment]::GetFolderPath($SpecialFolder);if([string]::IsNullOrWhiteSpace($p)){$p=Join-Path $env:USERPROFILE $FallbackName};$p}
function Invoke-SafeRobocopy{[CmdletBinding()]param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination,[string[]]$ExcludeDirectories=@(),[string[]]$ExcludeFiles=@(),[ValidateRange(0,20)][int]$RetryCount=2,[ValidateRange(0,60)][int]$WaitSeconds=2);if(-not(Test-Path -LiteralPath $Source -PathType Container)){Write-MigrationLog "Source not found, skipped: $Source" WARN;return};if(-not(Get-Command robocopy.exe -ErrorAction SilentlyContinue)){throw 'robocopy.exe was not found.'};New-DirectoryIfMissing $Destination -Confirm:$false;$a=@($Source,$Destination,'/E','/COPY:DAT','/DCOPY:DAT',"/R:$RetryCount","/W:$WaitSeconds",'/XJ','/FFT','/Z','/NP');if($ExcludeDirectories.Count){$a+='/XD';$a+=$ExcludeDirectories};if($ExcludeFiles.Count){$a+='/XF';$a+=$ExcludeFiles};& robocopy.exe @a 2>&1|ForEach-Object{Write-Host $_;if($script:MigrationLogFile){Add-Content $script:MigrationLogFile $_ -Encoding utf8}};$e=$LASTEXITCODE;if($e-ge 8){throw "Robocopy failed with exit code $e for '$Source'."};[pscustomobject]@{Source=$Source;Destination=$Destination;ExitCode=$e;Status='Success'}}
function Copy-OptionalMigrationItem{[CmdletBinding()]param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination);if(Test-Path -LiteralPath $Source){New-DirectoryIfMissing (Split-Path -Parent $Destination) -Confirm:$false;Copy-Item -LiteralPath $Source -Destination $Destination -Force -Recurse}}
function Test-UserMigrationPrerequisite{[CmdletBinding()]param([Parameter(Mandatory)][ValidateSet('Audit','Export','Import')][string]$Mode,[Parameter(Mandatory)][string]$BackupRoot);$r=@([pscustomobject]@{Check='Windows';Passed=$IsWindows;Detail=$PSVersionTable.OS},[pscustomobject]@{Check='PowerShell 7+';Passed=$PSVersionTable.PSVersion.Major-ge 7;Detail=$PSVersionTable.PSVersion},[pscustomobject]@{Check='USERPROFILE';Passed=-not[string]::IsNullOrWhiteSpace($env:USERPROFILE);Detail=$env:USERPROFILE},[pscustomobject]@{Check='Backup root';Passed=-not[string]::IsNullOrWhiteSpace($BackupRoot);Detail=$BackupRoot});if($Mode-in @('Export','Import')){$r+=[pscustomobject]@{Check='robocopy.exe';Passed=$null-ne(Get-Command robocopy.exe -ErrorAction SilentlyContinue);Detail='Required'}};if($Mode-eq'Import'){$r+=[pscustomobject]@{Check='Backup exists';Passed=Test-Path -LiteralPath $BackupRoot -PathType Container;Detail=$BackupRoot}};$r}
function Export-WindowsUserMigration{[CmdletBinding()]param([Parameter(Mandatory)][string]$BackupRoot,[Parameter(Mandatory)][bool]$IncludeDownloads,[Parameter(Mandatory)][bool]$IncludeWifiProfiles,[Parameter(Mandatory)][bool]$AllowClearTextWifiKeys,[Parameter(Mandatory)][System.Collections.IDictionary]$Settings);$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$dest=Join-Path $BackupRoot ("{0}_{1}_{2}"-f $env:COMPUTERNAME,$env:USERNAME,$stamp);New-DirectoryIfMissing $dest -Confirm:$false;$script:MigrationLogFile=Join-Path $dest 'Export.log';[ordered]@{ExportVersion=$Settings.ScriptVersion;ExportedAt=(Get-Date).ToString('o');ComputerName=$env:COMPUTERNAME;UserName=$env:USERNAME;UserDomain=$env:USERDOMAIN;UserProfile=$env:USERPROFILE;WindowsVersion=[Environment]::OSVersion.VersionString}|ConvertTo-Json|Set-Content (Join-Path $dest 'MigrationInfo.json') -Encoding utf8;$d=Join-Path $dest 'UserData';$f=[ordered]@{Desktop=Get-CurrentUserFolderPath Desktop Desktop;Documents=Get-CurrentUserFolderPath MyDocuments Documents;Pictures=Get-CurrentUserFolderPath MyPictures Pictures;Music=Get-CurrentUserFolderPath MyMusic Music;Videos=Get-CurrentUserFolderPath MyVideos Videos;Favorites=Get-CurrentUserFolderPath Favorites Favorites};if($IncludeDownloads){$f.Downloads=Join-Path $env:USERPROFILE 'Downloads'};foreach($x in $f.GetEnumerator()){Invoke-SafeRobocopy $x.Value (Join-Path $d $x.Key) -ExcludeFiles $Settings.ExcludedFilePatterns -RetryCount $Settings.RobocopyRetryCount -WaitSeconds $Settings.RobocopyWaitSeconds|Out-Null};$app=Join-Path $dest 'ApplicationSettings';Copy-OptionalMigrationItem (Join-Path $env:APPDATA 'Microsoft\Signatures') (Join-Path $app 'Outlook-Signatures');Copy-OptionalMigrationItem (Join-Path $env:APPDATA 'Microsoft\Templates') (Join-Path $app 'Office-Templates');Copy-OptionalMigrationItem (Join-Path $env:APPDATA 'Microsoft\Proof') (Join-Path $app 'Office-Proof');$b=Join-Path $dest 'Browser';Copy-OptionalMigrationItem (Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data\Default\Bookmarks') (Join-Path $b 'Chrome\Default\Bookmarks');Copy-OptionalMigrationItem (Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\User Data\Default\Bookmarks') (Join-Path $b 'Edge\Default\Bookmarks');$pst=Join-Path $dest 'Outlook-PST';New-DirectoryIfMissing $pst -Confirm:$false;Get-ChildItem $env:USERPROFILE -Filter '*.pst' -File -Recurse -ErrorAction SilentlyContinue|Copy-Item -Destination $pst -Force;$inv=Join-Path $dest 'Inventory';New-DirectoryIfMissing $inv -Confirm:$false;if(Get-Command Get-Printer -ErrorAction SilentlyContinue){Get-Printer|Select-Object Name,DriverName,PortName,Type,Shared,ShareName|Export-Csv (Join-Path $inv 'Printers.csv') -NoTypeInformation -Encoding utf8};Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=4' -ErrorAction SilentlyContinue|Select-Object DeviceID,ProviderName,VolumeName|Export-Csv (Join-Path $inv 'NetworkDrives.csv') -NoTypeInformation -Encoding utf8;if($IncludeWifiProfiles){if(-not$AllowClearTextWifiKeys){throw 'Wi-Fi export requires -AllowClearTextWifiKeys.'};$w=Join-Path $dest 'WiFi-Profiles-SENSITIVE';New-DirectoryIfMissing $w -Confirm:$false;& netsh.exe wlan export profile folder="$w" key=clear|Out-File (Join-Path $w 'Export-Output.txt')};[pscustomobject]@{Mode='Export';Status='Success';Path=$dest}}
function Find-LatestMigrationBackup{[CmdletBinding()]param([Parameter(Mandatory)][string]$BackupRoot);if(Test-Path (Join-Path $BackupRoot 'MigrationInfo.json')){return $BackupRoot};Get-ChildItem $BackupRoot -Directory|Where-Object{Test-Path (Join-Path $_.FullName 'MigrationInfo.json')}|Sort-Object LastWriteTime -Descending|Select-Object -First 1 -ExpandProperty FullName}
function Import-WindowsUserMigration{[CmdletBinding()]param([Parameter(Mandatory)][string]$BackupRoot,[Parameter(Mandatory)][bool]$IncludeWifiProfiles,[Parameter(Mandatory)][bool]$SkipNetworkDriveRestore,[Parameter(Mandatory)][bool]$SkipPrinterRestore,[Parameter(Mandatory)][System.Collections.IDictionary]$Settings);$src=Find-LatestMigrationBackup $BackupRoot;if(-not$src){throw 'No valid migration export found.'};$script:MigrationLogFile=Join-Path $src ("Import-{0}.log"-f(Get-Date -Format 'yyyyMMdd-HHmmss'));$d=Join-Path $src 'UserData';$t=[ordered]@{Desktop=Get-CurrentUserFolderPath Desktop Desktop;Documents=Get-CurrentUserFolderPath MyDocuments Documents;Pictures=Get-CurrentUserFolderPath MyPictures Pictures;Music=Get-CurrentUserFolderPath MyMusic Music;Videos=Get-CurrentUserFolderPath MyVideos Videos;Favorites=Get-CurrentUserFolderPath Favorites Favorites;Downloads=Join-Path $env:USERPROFILE 'Downloads'};foreach($x in $t.GetEnumerator()){$s=Join-Path $d $x.Key;if(Test-Path $s){Invoke-SafeRobocopy $s $x.Value -RetryCount $Settings.RobocopyRetryCount -WaitSeconds $Settings.RobocopyWaitSeconds|Out-Null}};$app=Join-Path $src 'ApplicationSettings';Invoke-SafeRobocopy (Join-Path $app 'Outlook-Signatures') (Join-Path $env:APPDATA 'Microsoft\Signatures')|Out-Null;Invoke-SafeRobocopy (Join-Path $app 'Office-Templates') (Join-Path $env:APPDATA 'Microsoft\Templates')|Out-Null;Invoke-SafeRobocopy (Join-Path $app 'Office-Proof') (Join-Path $env:APPDATA 'Microsoft\Proof')|Out-Null;$inv=Join-Path $src 'Inventory';if(-not$SkipNetworkDriveRestore){$p=Join-Path $inv 'NetworkDrives.csv';if(Test-Path $p){Import-Csv $p|Where-Object ProviderName|ForEach-Object{try{New-PSDrive -Name $_.DeviceID.TrimEnd(':') -PSProvider FileSystem -Root $_.ProviderName -Persist -Scope Global -ErrorAction Stop|Out-Null}catch{Write-MigrationLog $_.Exception.Message WARN}}}};if(-not$SkipPrinterRestore){$p=Join-Path $inv 'Printers.csv';if((Test-Path $p)-and(Get-Command Add-Printer -ErrorAction SilentlyContinue)){Import-Csv $p|Where-Object Name -Like '\\*'|ForEach-Object{try{Add-Printer -ConnectionName $_.Name -ErrorAction Stop}catch{Write-MigrationLog $_.Exception.Message WARN}}}};if($IncludeWifiProfiles){Get-ChildItem (Join-Path $src 'WiFi-Profiles-SENSITIVE') -Filter '*.xml' -File -ErrorAction SilentlyContinue|ForEach-Object{& netsh.exe wlan add profile filename="$($_.FullName)" user=current|Out-Null}};[pscustomobject]@{Mode='Import';Status='Success';Path=$src}}
function Invoke-WindowsUserMigration{[CmdletBinding(SupportsShouldProcess)]param([Parameter(Mandatory)][System.Collections.IDictionary]$Settings);$c=@(Test-UserMigrationPrerequisite $Settings.Mode $Settings.BackupRoot);$c|Format-Table -AutoSize|Out-Host;$bad=@($c|Where-Object{-not$_.Passed});if($bad.Count){throw "Prerequisite check failed: $($bad.Check -join ', ')"};if($Settings.Mode-eq'Audit'){Write-Host "`nAudit completed. No data was changed." -ForegroundColor Green;return $c};if($Settings.Mode-eq'Export'-and$PSCmdlet.ShouldProcess($Settings.BackupRoot,'Export Windows user data')){New-DirectoryIfMissing $Settings.BackupRoot -Confirm:$false;Export-WindowsUserMigration $Settings.BackupRoot $Settings.IncludeDownloads $Settings.IncludeWifiProfiles $Settings.AllowClearTextWifiKeys $Settings};if($Settings.Mode-eq'Import'-and$PSCmdlet.ShouldProcess($Settings.BackupRoot,'Import Windows user data')){Import-WindowsUserMigration $Settings.BackupRoot $Settings.IncludeWifiProfiles $Settings.SkipNetworkDriveRestore $Settings.SkipPrinterRestore $Settings}}
try{Invoke-WindowsUserMigration $Configuration}catch{Write-MigrationLog $_.Exception.Message ERROR;throw}
